    title_hi: "मानचित्रों का इतिहास",
    one_line: "From clay tablets to GPS, how maps represent both geography and power.",
    domain: "Cartography & History",
    domain_hi: "मानचित्रकला और इतिहास",
    reading_time: "8 min",
    original_source: "Geography Journal",
